function preview(s,options){const o=range(options),cutoff=[o.to,o.paymentDate,o.asOf].sort()[0],entries=s.claims.filter(c=>!o.employee||c.employee===o.employee).map(c=>{let reason,group='excluded';if(c.status==='Paid')reason='Already paid';else if(c.batch||['Reserved','Synced'].includes(c.status))reason='In another payout';else if(c.status!=='Approved'||c.approvals?.hr?.status!=='Approved')reason=c.status==='Rejected'?'Rejected':c.status==='Draft'?'Draft':'Not HR approved';else if(s.policies?.[c.category]?.covered===false||c.paidBy!=='Personal'||!c.receiptKey||!c.receiptHash)reason='Policy or proof hold';else if(!valid(c.date)||c.date>cutoff)reason='After cutoff / future';else if(c.date<o.from){group=o.includeLate?'late':'excluded';reason=o.includeLate?'Late unpaid · included':'Older unpaid · not selected';}else{group='period';reason='Approved in selected period';}return {claim:c,group,reason,cad:E.round((c.approved||0)*s.rates[c.currency])};});const selected=entries.filter(x=>x.group!=='excluded');return {options:o,cutoff,entries,selected,ids:selected.map(x=>x.claim.id),total:E.round(selected.reduce((a,x)=>a+x.cad,0)),periodCount:selected.filter(x=>x.group==='period').length,lateCount:selected.filter(x=>x.group==='late').length};}
function fingerprint(p){return JSON.stringify(p.selected.map(x=>[x.claim.id,x.claim.approved,x.claim.currency,x.claim.approvals.hr.at,x.cad]).sort((a,b)=>a[0].localeCompare(b[0])));}
function createRun(s,options,expectedIds,expectedFingerprint){const p=preview(s,options);if(expectedFingerprint&&expectedFingerprint!==fingerprint(p))throw Error('Amounts or FX changed since preview. Preview again.');if(!p.ids.length)throw Error('No eligible approved, unpaid expenses for these choices.');if(expectedIds&&JSON.stringify([...expectedIds].sort())!==JSON.stringify([...p.ids].sort()))throw Error('Claims changed since preview. Review the period again before preparing.');const identities=[...new Set(p.selected.map(x=>x.claim.employee))].map(name=>identity(s,name));const draft=structuredClone(s),run={identities,id:'RUN-'+crypto.randomUUID().slice(0,8),...p.options,cutoff:p.cutoff,createdAt:new Date().toISOString(),batchIds:[],lateIds:p.selected.filter(x=>x.group==='late').map(x=>x.claim.id)};for(const employee of new Set(p.selected.map(x=>x.claim.employee))){const ids=p.selected.filter(x=>x.claim.employee===employee).map(x=>x.claim.id);const b=E.batch(draft,employee,p.cutoff+'T23:59',p.options.paymentDate,ids);b.runId=run.id;b.periodFrom=run.from;b.periodTo=run.to;run.batchIds.push(b.id);}draft.payrollRuns||=[];draft.payrollRuns.unshift(run);E.log(draft,'HR','Prepared '+run.id+' · '+p.periodCount+' period / '+p.lateCount+' late unpaid claims');Object.assign(s,draft);return run;}
function runRows(s,id){const run=s.payrollRuns?.find(x=>x.id===id);if(!run)throw Error('Choose a payroll run.');if(new Set(run.batchIds).size!==run.batchIds.length)throw Error('Duplicate payout batch in run.');return run.batchIds.flatMap(bid=>{const b=s.batches.find(x=>x.id===bid);if(!b)throw Error('A payout batch is missing.');if(b.status==='Cancelled')return [];if(!['Reserved','Synced','Failed','Paid'].includes(b.status))throw Error('Resolve held or uncertain payouts before using this run.');return E.exportRows(s,bid).map(r=>{const who=run.identities?.find(e=>e.employee===r.employee);if(!who)throw Error('Legacy ID-only run: keep its existing payroll handoff; email export is blocked.');if(b.status!=='Paid'){const current=identity(s,r.employee);if(current.email!==who.email||current.employeeId!==who.employeeId)throw Error('Employee email changed since freeze. Review mapping before exporting.');}return {...r,employeeId:who.employeeId,email:who.email,runId:run.id,from:run.from,to:run.to,group:run.lateIds.includes(r.claim)?'Late unpaid':'Selected period',batchStatus:b.status,payrollReady:['Synced','Paid'].includes(b.status)&&E.reconcile(s,bid).ok};});});}
function summary(s,id){const rows=runRows(s,id),groups=new Map();for(const r of rows){const key=r.employeeId;if(!groups.has(key))groups.set(key,{runId:r.runId,employeeId:key,employee:r.employee,email:r.email,from:r.from,to:r.to,periodCAD:0,lateCAD:0,totalCAD:0,claims:0,ready:true,paid:true});const g=groups.get(key);if(g.employee!==r.employee)throw Error('Duplicate Employee ID. Fix the directory before payroll.');g[r.group==='Late unpaid'?'lateCAD':'periodCAD']=E.round(g[r.group==='Late unpaid'?'lateCAD':'periodCAD']+r.cad);g.totalCAD=E.round(g.totalCAD+r.cad);g.claims++;g.ready&&=r.payrollReady;g.paid&&=r.paymentStatus==='Paid';}return [...groups.values()];}
function syncRun(s,id,fail=false){const run=s.payrollRuns?.find(x=>x.id===id);if(!run)throw Error('Choose a payroll run.');runRows(s,id);const draft=structuredClone(s);for(const bid of run.batchIds){const b=draft.batches.find(x=>x.id===bid);if(['Cancelled','Paid'].includes(b.status))continue;E.sync(draft,bid,fail);}Object.assign(s,draft);return summary(s,id);}
function autoSync(s,options,fail=false){const o=range(options),draft=structuredClone(s);draft.payrollRuns||=[];let run=draft.payrollRuns.find(r=>r.from===o.from&&r.to===o.to&&r.employee===o.employee&&r.batchIds.some(id=>draft.batches.find(b=>b.id===id)?.status!=='Cancelled'));const reused=!!run;if(!run)run=createRun(draft,o);checkLink(draft,run);syncRun(draft,run.id,fail);const rows=summary(draft,run.id);if(!rows.length||rows.some(r=>!r.ready))throw Error('Run is not ready for payroll.');draft.payrollSummaryRows=[...(draft.payrollSummaryRows||[]).filter(r=>r.runId!==run.id),...rows.map(r=>({...r,key:run.id+':'+r.email,exportStatus:'READY'}))];const activeRun=draft.payrollRuns.find(r=>r.id===run.id);activeRun.handoffAt||=new Date().toISOString();activeRun.syncAt=new Date().toISOString();E.log(draft,'HR','Email matched and demo-synced '+run.id+'; '+rows.length+' unique employee rows');Object.assign(s,draft);return {runId:run.id,reused,rows};}
